import { useEffect } from 'react';
import { load } from '@2gis/mapgl';
// Импортируем плагин для маршрутов
import { Directions } from '@2gis/mapgl-directions'; 

// @ts-ignore
const geoData = require('./data/data.json');

const MAP_CENTER = [55.9678, 54.7431];

export default function Mapgl() {
    useEffect(() => {
        let map: any = undefined;
        let directions: any = undefined; // Переменная для маршрутизатора

        load().then((mapgl) => {
            map = new mapgl.Map('map-container', {
                center: MAP_CENTER,
                zoom: 12,
                key: '8251453a-0c25-4eac-adb2-88f4cca6e4f4',
                style: '45cb9720-dbb6-4242-9300-56545bcf25e1',
            });

            const touristCoords = [
                [55.9264, 54.7188], // Памятник Салавату Юлаеву
                [55.9320, 54.7215], // Конгресс-холл Торатау
                [55.9400, 54.7250], // Гостиный двор
                [55.9450, 54.7260], // Театр оперы и балета
                [55.9500, 54.7300], // Арт-КВАДРАТ
            ];

            const touristSource = new mapgl.GeoJsonSource(map, {
                data: {
                    type: 'FeatureCollection',
                    features: touristCoords.map((coord, index) => ({
                        type: 'Feature',
                        geometry: { type: 'Point', coordinates: coord },
                        properties: { name: `Точка ${index + 1}` }
                    }))
                },
                attributes: { purpose: 'tourist' },
            });

            const touristLayer = {
                id: 'tourist-layer',
                type: 'point',
                filter: ['match', ['sourceAttr', 'purpose'], ['tourist'], true, false],
                style: {
                    iconImage: 'car', 
                    iconWidth: 20,
                    textField: ['get', 'name'],
                    textColor: '#E03D3D',
                    textHaloColor: '#ffffff',
                    textHaloWidth: 2,
                }
            };

            map.on('styleload', () => {
                map.addLayer(touristLayer);

                directions = new Directions(map, {
                    directionsApiKey: '8251453a-0c25-4eac-adb2-88f4cca6e4f4',
                });

                directions.pedestrianRoute({
                    points: touristCoords,
                });
            });
        });

        return () => {
            directions && directions.clear();
            map && map.destroy();
        };
    }, []);

    return null;
}